urlset:
{#- Posts whose original copy lives on the resume site are left out, so Google
    is only asked to index pages that are canonical here. -#}
{%- for sitemap_entry in entries %}
{%- set canonical = sitemap_entry.extra.canonical | default(value="") %}
{%- if not canonical %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
